":-0.04,"category":"Pintura","role":"operario_5"}]$json$::jsonb; begin
insert into public.inventory_items(product_code,product_name,unit,warehouse_code,system_quantity,unit_value,total_value,category) select code,name,unit,'01',quantity,unit_value,total_value,category from jsonb_to_recordset(catalog) as x(code text,name text,unit text,quantity numeric,unit_value numeric,total_value numeric,category text,role text) on conflict(product_code) do update set product_name=excluded.product_name,unit=excluded.unit,system_quantity=excluded.system_quantity,unit_value=excluded.unit_value,total_value=excluded.total_value,category=excluded.category;
insert into public.count_tasks(inventory_item_id,product_code,product_name,unit,assigned_role) select i.id,i.product_code,i.product_name,i.unit,x.role from jsonb_to_recordset(catalog) as x(code text,name text,unit text,quantity numeric,unit_value numeric,total_value numeric,category text,role text) join public.inventory_items i on i.product_code=x.code on conflict(inventory_item_id) do update set product_code=excluded.product_code,product_name=excluded.product_name,unit=excluded.unit,assigned_role=excluded.assigned_role;
end $seed$;
